create table schools(id uuid primary key,name varchar(100) not null,created_at timestamptz not null default now());
insert into schools(id,name) values ('00000000-0000-4000-8000-000000000001','한빛학교');
create table accounts(id uuid primary key,school_id uuid not null references schools(id),role varchar(10) not null check(role in ('STUDENT','TEACHER','ADMIN')),name varchar(50) not null,staff_login_id varchar(40) unique,password_hash varchar(255) not null,password_version integer not null default 1 check(password_version>=1),must_change_password boolean not null default false,created_at timestamptz not null default now(),check((role='STUDENT' and staff_login_id is null) or (role in ('TEACHER','ADMIN') and staff_login_id is not null)));
create index accounts_school_idx on accounts(school_id);
create table classrooms(id uuid primary key,school_id uuid not null references schools(id),grade_label varchar(20) not null,class_number integer not null check(class_number between 1 and 99),join_code varchar(8) not null,start_date date not null,created_at timestamptz not null default now(),constraint uq_classroom_tuple unique(school_id,grade_label,class_number),constraint uq_join_code unique(join_code));
create table classroom_teachers(classroom_id uuid not null references classrooms(id),teacher_account_id uuid not null references accounts(id),primary key(classroom_id,teacher_account_id));
create index classroom_teachers_teacher_idx on classroom_teachers(teacher_account_id);
create table student_profiles(account_id uuid primary key references accounts(id),classroom_id uuid not null references classrooms(id),student_number integer not null check(student_number between 1 and 999),nickname varchar(20) not null,constraint uq_student_number unique(classroom_id,student_number));
